package com.bank.replication;

import java.util.*;
import java.util.logging.*;

public class ReplicationDemo {
    private static final Logger log = Logger.getLogger("Repl");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Node primary = new Node("primary", true);
        Node r1 = new Node("replica-1", false);
        Node r2 = new Node("replica-2", false);
        ReplicationManager mgr = new ReplicationManager(primary, List.of(r1, r2));

        // Write goes to primary, then replicates (async, slight lag)
        mgr.write("balance:SAV2001", "950000");
        log.info(() -> "primary balance = " + primary.read("balance:SAV2001"));

        // Replica may lag: read BEFORE replication completes shows stale/absent
        log.info(() -> "replica read (may lag) = " + mgr.read("balance:SAV2001", false));

        // Replicate to replicas, then reads are consistent
        mgr.replicate();
        log.info(() -> "replica read after replicate = " + mgr.read("balance:SAV2001", false));

        // Read-your-writes: a user who just wrote reads from primary
        log.info(() -> "read-your-writes = " + mgr.read("balance:SAV2001", true));

        // Failover: primary crashes → promote most up-to-date replica, fence old
        log.warning("Primary crashed!");
        mgr.failover();
        mgr.write("balance:SAV2001", "930000");  // new primary accepts writes
        log.info(() -> "after failover, new primary balance = " + mgr.read("balance:SAV2001", true));
    }
}

