package com.bank.replication;

import java.util.*;

public class Node {
    private final String name;
    private boolean primary;
    private boolean fenced = false;       // fenced nodes cannot accept writes
    private final Map<String,String> store = new HashMap<>();

    public Node(String name, boolean primary) { this.name = name; this.primary = primary; }
    public String name() { return name; }
    public boolean isPrimary() { return primary; }
    public void setPrimary(boolean p) { this.primary = p; }
    public void fence() { this.fenced = true; }
    public boolean isFenced() { return fenced; }

    public void apply(String key, String value) { store.put(key, value); }
    public String read(String key) { return store.getOrDefault(key, "<absent>"); }
}
